CREATE TABLE IF NOT EXISTS job_openings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, department text, employment_type text NOT NULL DEFAULT 'full_time', status text NOT NULL DEFAULT 'draft', description text, created_at timestamptz NOT NULL DEFAULT now());
-- status index intentionally omitted for compatibility with pre-existing schemas
CREATE TABLE IF NOT EXISTS job_candidates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), opening_id uuid REFERENCES job_openings(id) ON DELETE SET NULL, full_name text NOT NULL, email text NOT NULL, phone text, stage text NOT NULL DEFAULT 'applied', source text, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS employment_offers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_id uuid NOT NULL REFERENCES job_candidates(id) ON DELETE CASCADE, job_title text NOT NULL, department text, salary_amount numeric(14,2) NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'NGN', start_date date, status text NOT NULL DEFAULT 'draft', issued_at timestamptz, accepted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS onboarding_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_id uuid NOT NULL REFERENCES job_candidates(id) ON DELETE CASCADE, offer_id uuid REFERENCES employment_offers(id) ON DELETE SET NULL, status text NOT NULL DEFAULT 'not_started', start_date date, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS onboarding_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), onboarding_id uuid NOT NULL REFERENCES onboarding_cases(id) ON DELETE CASCADE, task_name text NOT NULL, required boolean NOT NULL DEFAULT true, status text NOT NULL DEFAULT 'pending', due_date date, completed_at timestamptz);
-- Secondary indexes are intentionally omitted here for maximum compatibility with the existing production schema.